-- Generated by scripts/build_compiled.py from src/fraudrules/rules/first-party/fp-002-payment-spend-return.yaml. Do not edit.
-- FP-002 Card payment spent before it clears, then returned unpaid
SELECT DISTINCT 'FP-002' AS rule_id, 'transactions' AS anchor_table, s2.id AS anchor_id
FROM transactions AS s2
JOIN transactions AS s1 ON s1.account_id = s2.account_id AND s1.ts < s2.ts AND (s1.account_type = 'card' AND s1.direction = 'out' AND s1.txn_type IN ('purchase', 'cash_advance') AND s1.amount_cents >= 50000)
JOIN transactions AS s0 ON s0.account_id = s2.account_id AND s0.ts < s1.ts AND s0.ts > s2.ts - 864000 AND (s0.account_type = 'card' AND s0.txn_type = 'payment' AND s0.direction = 'in' AND s0.channel = 'ach' AND s0.amount_cents >= 100000)
WHERE (s2.account_type = 'card' AND s2.txn_type = 'return' AND s2.return_code IN ('R01', 'R02', 'R03', 'R04', 'R08', 'R09', 'R16', 'R20'));
